// Définition des 5 piliers éditoriaux de Crush.lu avec mascotte 3D et scènes associées
const pillars = [
  {
    id: 'events',
    name: 'Events & Speed Dating',
    description: 'Upcoming events in Luxembourg, venues (Grund, Belval, Clausen), published event details only; no invented urgency or ratios.',
    cta: 'Check upcoming events and reserve your spot at https://crush.lu/en/',
    ghostScene: 'ghost_scene_party.svg',
    mascotAction: 'The 3D Crush ghost mascot is joyfully mingling at a lively afterwork gathering in Luxembourg Grund, holding a tiny glowing mocktail glass with cozy warm string lights in the background'
  },
  {
    id: 'proof',
    name: 'Numbers & Real Proof',
    description: 'Real member community, verified profiles, active daters in Luxembourg, successful connections, transparent stats without generic claims.',
    cta: 'Join Luxembourg\'s verified dating community on crush.lu',
    ghostScene: 'ghost_scene_approved.svg',
    mascotAction: 'The 3D Crush ghost mascot proudly standing next to an elegant glowing green checkmark badge, celebrating genuine human connections and verified single members in Luxembourg'
  },
  {
    id: 'trust',
    name: 'Trust, Safety & LuxID',
    description: 'Why Crush is different: LuxID national identity verification, anti-catfish, identity verification helps reduce impersonation, respectful offline encounters over superficial swiping.',
    cta: 'Experience safe, verified dating at crush.lu',
    ghostScene: 'ghost_scene_unlock.svg',
    mascotAction: 'The 3D Crush ghost mascot holding a subtle miniature golden key with a glowing neon pink heart, symbolizing verified LuxID safety, identity verification, and genuine trust'
  },
  {
    id: 'coach_tips',
    name: 'Dating Coach Insights',
    description: 'Practical advice for modern dating in Luxembourg, how to break the ice, dealing with expat/local social bubbles, authentic body language.',
    cta: 'Get guidance from Crush coaches at crush.lu',
    ghostScene: 'ghost_scene_chatting_pair.svg',
    mascotAction: 'Two cute 3D Crush ghost figurines having an animated, warm coffee conversation on a bistro terrace overlooking the Alzette river in Luxembourg'
  },
  {
    id: 'founding_members',
    name: 'Founding Community & Connect',
    description: 'Celebrating early members, Connect beta features, weekly deliberate matches, joining the founding circle before 2027.',
    cta: 'Explore the Crush.lu community at https://crush.lu/en/',
    ghostScene: 'ghost_scene_inlove.svg',
    mascotAction: 'The 3D Crush ghost mascot sitting warmly on a bench in Luxembourg Ville at sunset, with a vibrant glowing neon pink heart floating right above it'
  }
];

const now = new Date();
const local = new Date(now.toLocaleString('en-US', {timeZone:'Europe/Luxembourg'}));
const day = local.getDay();
const week = Math.floor((Date.UTC(local.getFullYear(),local.getMonth(),local.getDate()) - Date.UTC(2026,8,28))/(7*86400000));
const slot = week*2 + (day >= 4 ? 1 : 0);
const override = $json.body?.topic;
const selected = override ? pillars.find(t=>t.id===override) : pillars[((slot%pillars.length)+pillars.length)%pillars.length];
if(!selected) throw new Error('Unknown topic');
const mapping = {events:'promo',proof:'milestone',coach_tips:'dating_tip',trust:'community',founding_members:'community'};
return [{json:{...selected,kind:"editorial",hubPillar:mapping[selected.id]}}];

const raw = $json.output || $json.text;
if (typeof raw !== 'string') throw new Error('LLM returned no text');
let parsed; try { parsed = JSON.parse(raw); } catch { throw new Error('Copy must be strict JSON; repair the prompt before sending'); }
const selected = $('Select Topic').first().json;
const count = selected.kind === 'carousel' ? 5 : 1;
if (!Array.isArray(parsed.slides) || parsed.slides.length !== count) throw new Error('Incomplete slide script');
for (const s of parsed.slides) {
  if (typeof s.title !== 'string' || !s.title.trim() || s.title.length > 100 || typeof s.body !== 'string' || s.body.length > 300) throw new Error('Slide text exceeds readable limits');
}
for (const key of ['caption_en','caption_fr']) {
  if (typeof parsed[key] !== 'string' || !parsed[key].trim() || parsed[key].length > 1500) throw new Error('Caption exceeds Hub 1500 / Instagram 2199 / LinkedIn 3000 limits');
  if ((parsed[key].match(/#[\p{L}\p{N}_]+/gu)||[]).length > 5) throw new Error('Too many hashtags');
}
if (typeof parsed.visualPrompt !== 'string' || !parsed.visualPrompt.trim() || parsed.visualPrompt.length > 2000) throw new Error('Invalid image prompt');
const script = {slides:parsed.slides, caption_en:parsed.caption_en, caption_fr:parsed.caption_fr,
  visualPrompt:parsed.visualPrompt, ghostScene:selected.ghostScene, language:'en', pillar:selected.hubPillar};
return [{json:{script,run_key:`${$workflow.id}:${$execution.id}`}}];

const raw = $json.image_base64;
if (!raw) throw new Error('Renderer returned no reference');
const reference = await this.helpers.prepareBinaryData(Buffer.from(raw,'base64'), 'reference.png', 'image/png');
return [{json:$json, binary:{reference}}];

const cover = await this.helpers.getBinaryDataBuffer(0, 'cover');
const previous = $('Validate Script').first().json;
return [{json:{...previous,cover_base64:cover.toString('base64')}}];
